CREATE MATERIALIZED VIEW gold.per_day_metrics_mv TO gold.daily_session_metrics (`day_bucket` DateTime('UTC'), `platform` LowCardinality(String), `video_resolution` LowCardinality(String), `country` LowCardinality(String), `audio_languages` AggregateFunction(groupUniqArray, String), `subtitle_languages` AggregateFunction(groupUniqArray, String), `category` LowCardinality(String), `show_name` LowCardinality(String), `title` LowCardinality(String), `active_users_state` AggregateFunction(uniqExact, FixedString(64)), `active_session_state` AggregateFunction(uniqExact, FixedString(64))) AS SELECT toStartOfDay(hour_bucket) AS day_bucket, platform, video_resolution, country, groupUniqArrayMergeState(audio_languages) AS audio_languages, groupUniqArrayMergeState(subtitle_languages) AS subtitle_languages, category, show_name, title, uniqExactMergeState(active_users_state) AS active_users_state, uniqExactMergeState(active_session_state) AS active_session_state FROM gold.hourly_session_metrics GROUP BY day_bucket, platform, video_resolution, country, category, show_name, title